 fun onMap(pixels:IntArray,w:Int,h:Int):Boolean {
  if(w!=540 || h !in 1000..1450 || pixels.size!=w*h)return false
  var yellow=0
  for(y in h*93/100..h*97/100)for(x in w*66/100..w*75/100){
   val c=pixels[y*w+x];val r=c ushr 16 and 255;val g=c ushr 8 and 255;val b=c and 255
   if(r>175 && g>110 && b<95 && r>g)yellow++
  }
  if(yellow<45)return false
  for(width in 90..106 step 8)for(cy in h*55/1000..h*11/100 step 4)
   for(cx in 262..278 step 4){
    val height=width*19/54;var error=0
    for(gy in 0..7)for(gx in 0..23){
     val c=pixels[(cy-height/2+(gy*2+1)*height/16)*w+cx-width/2+(gx*2+1)*width/48]
     val ref=header[gy*24+gx]
     error+=kotlin.math.abs((c ushr 16 and 255)-(ref ushr 16 and 255))+
      kotlin.math.abs((c ushr 8 and 255)-(ref ushr 8 and 255))+
      kotlin.math.abs((c and 255)-(ref and 255))
    }
    if(error/(24*8*3)<22)return true
   }
