 fun detect(pixels:IntArray,w:Int,h:Int):Point? {
  if(w!=540 || h !in 1000..1450 || pixels.size!=w*h)return null
  var best:Point?=null;var bestError=26
  for(size in 72..84 step 4)for(y in (h*58/100)..(h*84/100) step 4)
   for(x in (w*79/100)..(w*96/100) step 4){
    val left=x-size/2;val top=y-size/2
    if(left<0 || top<0 || left+size>=w || top+size>=h)continue
    var error=0;var samples=0;var close=0
